script.text:

function load$Grid(g) {
	g.add_onResponseComplete(on$GridCashDisbursement$ResponseComplete);
	g.add_commandEvent(on$GridCashDisbursement$ExecuteCommand);
	&ddScriptGridLoad;

}
function dispose$Grid(g) {
	try {g.remove_commandEvent(on$GridCashDisbursement$ExecuteCommand);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridCashDisbursement$ResponseComplete);} catch (ex) {}
	&ddScriptGridDispose;
}
function on$GridCashDisbursement$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, v = g._language == 'v', id = g.get_id();
	switch (action) {
		case 'ImportData':
			show$Form(g, 'DCTranImport');
			break;
		case 'Download':
			&UserDefinedDownload;
			break;
		&APVHistoryExecute;
		case 'Update':
			if (g._activeRow == -1 || g._rowCount == 0) break;
			g.showForm('UpdateDCTran');

			break;
		default:
			break;
	}
}
function updateNgayHSTT(g, row, ngay_hs_tt) {
	var o = g._getItem(row,1);
	o._lastValue = '';
	o.row = row;
	console.log(ngay_hs_tt);

	g.request(o,'Update','Update', ['stt_rec', 'ngay_ct', ['ngay_hs_tt', 'DateTime', ngay_hs_tt] ], null, true);
}

function on$GridCashDisbursement$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, v = g._language == 'v';
	switch (context) {
		case 'Download':
			g._key = result[0].Value;
			break;
		&APVHistoryResponse;
		&GNEditExecute;
		&ddScriptGridResponseComplete;
		case 'Update':
			if (result[0].Value == 0) {
				$message.show(v ? 'Trạng thái chứng từ hiện tại không cho phép cập nhật': 'Current voucher status is not allowed to update');
				break;
			}			
			console.log('go -1');
			g.goToPage(-1);
			break;
		default:
			break;
	}
}
&ddScriptGridRender;
function show$Form(g, c) {(g._authorize == 1) && (!g._denyNew) ? g.showForm(c) : $message.show(g._denyMessage ? g._denyMessage : $df.getResources(g._language, "Message.NotAccess"));}

			&DowloadScript;
			&FlowMultiScript;
			&VisibleFieldScript;
			&GNEditScript;

grid.response:


				&CreateTicket;
select @ticket as value
return






declare @q nvarchar(512), @p char(6)
set @p = convert(char(6), @ngay_ct, 112)
set @q = 'if exists(select 1 from m52$%Partition where stt_rec = @stt_rec and status in (''2'', ''3'', ''4'', ''*'')) select 0 as result
				else begin 
					update m52$%Partition set ngay_hs_tt = @ngay_hs_tt where stt_rec = @stt_rec;
					select 1 as result
				end';
set @q = replace(@q, '%Partition', @p)	
exec sp_executesql @q, N'@ngay_hs_tt smalldatetime, @stt_rec char(13)', @ngay_hs_tt, @stt_rec  




		&APVHistoryGetData;
		&ddResponse;

